# Top-level VHDL design of my quantized transformer (QuantTinyTransformer).
# Simplified from Ling et al., TinyTransformer4TS (MIT license), models/quant/design.py:
# same behaviour and output files, but it stores only the layer designs, writes them
# in a loop and leaves out Ling's board wrapper (skeleton).
#
# What it writes (save_to):
#   <layer name>/...                  VHDL of each of the 5 layers (generated by the library)
#   <name>/<name>.vhd                 top level: connects the 5 layers (transformer.tpl.vhd)
#   <name>/pos_info_rom.vhd           ROM with the quantized positional encoding
#   <name>/<name>_tb.vhd              testbench (transformer_tb.tpl.vhd)
# The two templates must be in this folder: the library looks for them next to this file.

from itertools import chain

from elasticai.creator.file_generation.savable import Path
from elasticai.creator.file_generation.template import InProjectTemplate, module_to_package
from elasticai.creator.vhdl.auto_wire_protocols.port_definitions import create_port
from elasticai.creator.vhdl.design.design import Design
from elasticai.creator.vhdl.design.ports import Port
from elasticai.creator.vhdl.shared_designs.rom import Rom

POS_INFO_ROM = "pos_info_rom"   # must match ${pos_info_rom_name} in transformer.tpl.vhd


class Transformer(Design):
    def __init__(self, name, data_width, input_linear, inputs_pos_info, pos_info_addition,
                 encoder, avg_pooling, output_linear, work_library_name="work"):
        # the layers must come from a precomputed model (to_integer): their designs
        # contain the integer weights, biases and multiply-and-shift factors
        super().__init__(name=name)
        self._data_width = data_width                    # = quant_bits (6)
        self._pos_info = inputs_pos_info                 # quantized PE, [window][d_model] integers
        self._work_library_name = work_library_name      # VHDL library ("work" = Vivado default)

        # one VHDL design per layer; the encoder is a container, its design comes from .sequential
        self.input_linear_design = input_linear.create_design(name=input_linear.name)
        self.pos_info_addition_design = pos_info_addition.create_design(name=pos_info_addition.name)
        self.encoder_design = encoder.sequential.create_design(name=encoder.name)
        self.avg_pooling_design = avg_pooling.create_design(name=avg_pooling.name)
        self.output_linear_design = output_linear.create_design(name=output_linear.name)

    @property
    def port(self) -> Port:
        # outside interface: 6-bit values, 192 in (24 x 8), 1 out
        return create_port(
            x_width=self._data_width,
            y_width=self._data_width,
            x_count=self.input_linear_design._x_count,
            y_count=self.output_linear_design._y_count,
        )

    def _template(self, file_name, **parameters):
        # fill a template from this folder; all values must be strings
        return InProjectTemplate(
            package=module_to_package(self.__module__),
            file_name=file_name,
            parameters={k: str(v) for k, v in parameters.items()},
        )

    def save_to(self, destination: Path) -> None:
        first, last = self.input_linear_design, self.output_linear_design
        add, gap = self.pos_info_addition_design, self.avg_pooling_design  # gap = global average pooling

        # 1) the 5 layers, each in its own folder
        for design in (first, add, self.encoder_design, gap, last):
            design.save_to(destination.create_subpath(design.name))

        top = destination.create_subpath(self.name)

        # 2) top level: wires the layers together (transformer.tpl.vhd)
        top.create_subpath(self.name).as_file(".vhd").write(self._template(
            "transformer.tpl.vhd",
            name=self.name,
            data_width=self._data_width,
            work_library_name=self._work_library_name,
            x_addr_width=first._x_addr_width,
            y_addr_width=last._y_addr_width,
            input_linear_name=first.name,
            input_linear_x_addr_width=first._x_addr_width,
            input_linear_y_addr_width=first._y_addr_width,
            add_pos_info_name=add.name,
            add_pos_info_x_addr_width=add._x_addr_width,
            add_pos_info_y_addr_width=add._y_addr_width,
            pos_info_rom_name=POS_INFO_ROM,
            encoder_name=self.encoder_design.name,
            avgpooling_name=gap.name,
            gap_x_addr_width=gap._x_addr_width,
            gap_y_addr_width=gap._y_addr_width,
            output_linear_name=last.name,
            output_linear_x_addr_width=last._x_addr_width,
            output_linear_y_addr_width=last._y_addr_width,
        ))

        # 3) ROM with the positional encoding: [24][24] -> 576 integers, second input of add_pos_info
        Rom(name=POS_INFO_ROM, data_width=self._data_width,
            values_as_integers=list(chain(*self._pos_info))).save_to(top.create_subpath(POS_INFO_ROM))

        # 4) testbench: reads ./data/<name>_q_x.txt, compares with ./data/<name>_q_y.txt
        top.create_subpath(self.name).as_file("_tb.vhd").write(self._template(
            "transformer_tb.tpl.vhd",
            name=self.name,
            data_width=self._data_width,
            work_library_name=self._work_library_name,
            x_addr_width=first._x_addr_width,
            y_addr_width=last._y_addr_width,
            x_count=first._x_count,
            y_count=last._y_count,
        ))
